import type { readVendorBilling } from "./vendor-billing-service";
import { VendorBillingError, billingDate, billingMoney } from "@/lib/vendor-billing";
type Model=Awaited<ReturnType<typeof readVendorBilling>>;
const esc=(value:unknown)=>String(value??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;");
export function vendorBillingPrint(model:Model,params:URLSearchParams){
  const id=params.get("documentId"),settlementId=params.get("settlementId"),agreementId=params.get("agreementId");let body="",title="Vendor account statement";
  const row=(values:unknown[])=>`<tr>${values.map(v=>`<td>${esc(v)}</td>`).join("")}</tr>`;
  const side=(value:string)=>value==="RECEIVABLE"?"They owe us":"We owe them";
  if(agreementId){
    const a=model.agreements.find(a=>a.id===agreementId);if(!a)throw new VendorBillingError("Agreement not found.",404);
    title=a.kind==="REPAYMENT"?"Repayment schedule":"Recurring billing schedule";
    const scheduled=model.documents.filter(d=>d.agreementId===a.id);
    body=`<h2>${esc(a.title)}</h2><p>${side(a.direction)} | ${billingMoney(a.amountCents)} monthly | ${a.active?"Active":"Paused"}</p><p>First due: ${esc(a.startDate)} | Last due: ${esc(a.endDate||"Until paused / ended")}</p><p>Recorded terms / source: ${esc(a.terms)}</p>${a.principalCents?`<p>Original principal: ${billingMoney(a.principalCents)}. Principal is recorded once; installments are not new charges.</p>`:"<p>Monthly invoices are generated as drafts and require approval. This schedule is a record of entered terms, not a replacement for the signed agreement.</p>"}<table><thead><tr><th>Due date</th><th>Invoice</th><th>Scheduled</th><th>Outstanding</th></tr></thead><tbody>${scheduled.flatMap(d=>d.dueItems.map(i=>row([i.dueDate,d.number,billingMoney(i.amountCents),billingMoney(i.outstandingCents)]))).join("")}</tbody></table>`;
  }else if(id){
    const d=model.documents.find(d=>d.id===id);if(!d)throw new VendorBillingError("Invoice not found.",404);
    title=d.kind==="OPENING_BALANCE"?"Existing balance record":d.direction==="RECEIVABLE"?"Invoice":"Vendor bill record";
    body=`<h2>${esc(d.number)} <small>${esc(d.status)}</small></h2><p>${esc(d.title)}</p><p>${side(d.direction)} | Issued ${esc(d.issueDate)} | Due ${esc(d.dueDate)}</p><p>Source: ${esc(d.sourceReference)}</p><table><thead><tr><th>Description</th><th>Work ticket</th><th>Amount</th></tr></thead><tbody>${d.lines.map(l=>row([l.description,model.jobs.find(j=>j.id===l.workJobId)?.number||"",billingMoney(l.amountCents)])).join("")}${row(["Separately entered tax","",billingMoney(d.taxCents)])}${row(["Total","",billingMoney(d.amountCents)])}${row(["Applied payments / credits / offsets","",billingMoney(d.appliedCents)])}${row(["Outstanding","",billingMoney(d.balanceCents)])}</tbody></table><p>${d.direction==="PAYABLE"?"Record of the supplier's bill; retain the original supplier invoice.":d.kind==="OPENING_BALANCE"?"Existing principal recorded once. Scheduled repayments do not create new revenue charges.":"Please include the invoice number with your payment."}</p>${d.status==="DRAFT"?"<p class='warning'>DRAFT - NOT APPROVED OR ISSUED</p>":""}`;
  }else if(settlementId){
    const s=model.settlements.find(s=>s.id===settlementId);if(!s)throw new VendorBillingError("Payment record not found.",404);
    title=s.kind==="OFFSET"?"Approved offset settlement":s.kind==="RECEIPT"?"Payment receipt":s.kind==="PAYMENT"?"Payment remittance":s.kind==="CREDIT"?"Credit / adjustment record":"Reversal record";
    body=`<h2>${esc(s.reference)}</h2><p>${esc(s.date)} | ${esc(s.kind)} | ${billingMoney(s.amountCents)}</p><p>${esc(s.reason)}</p><table><thead><tr><th>Invoice</th><th>Direction</th><th>Allocation</th></tr></thead><tbody>${s.allocations.map(a=>{const d=model.documents.find(d=>d.id===a.documentId);return row([d?.number,side(d?.direction||""),billingMoney(a.amountCents)]);}).join("")}</tbody></table><p>Unapplied: ${billingMoney(s.unappliedCents)}. ${s.reversed?"This record has been reversed; the original is retained.":""}</p><p>${s.reconciledAt?`Reconciled evidence: ${esc(s.reconciliationReference)}`:"Recorded in the vendor ledger; bank reconciliation has not been confirmed."}</p>`;
  }else{
    const from=billingDate(params.get("from")||model.today.slice(0,7)+"-01"),through=billingDate(params.get("through")||model.today);if(from>through)throw new VendorBillingError("Statement start must precede its end.");
    const docs=model.documents.filter(d=>["POSTED","DISPUTED"].includes(d.status)&&d.issueDate<=through);
    const allocations=model.settlements.flatMap(s=>s.allocations.map(a=>({...a,date:a.effectiveDate.toISOString().slice(0,10),kind:s.kind,reference:s.reference}))).filter(a=>a.date<=through&&docs.some(d=>d.id===a.documentId));
    body=`<p>${esc(from)} through ${esc(through)} - America/Chicago business dates</p><table><thead><tr><th>Direction</th><th>Opening</th><th>New obligations</th><th>Applied settlements</th><th>Closing outstanding</th></tr></thead><tbody>${["RECEIVABLE","PAYABLE"].map(direction=>{
      const selected=docs.filter(d=>d.direction===direction),ids=new Set(selected.map(d=>d.id)),applied=allocations.filter(a=>ids.has(a.documentId));
      const opening=selected.filter(d=>d.issueDate<from).reduce((sum,d)=>sum+d.amountCents,0)-applied.filter(a=>a.date<from).reduce((sum,a)=>sum+a.amountCents,0);
      const charges=selected.filter(d=>d.issueDate>=from).reduce((sum,d)=>sum+d.amountCents,0),settled=applied.filter(a=>a.date>=from).reduce((sum,a)=>sum+a.amountCents,0);
      return row([side(direction),billingMoney(opening),billingMoney(charges),billingMoney(settled),billingMoney(opening+charges-settled)]);
    }).join("")}</tbody></table><h2>Invoices and original balances</h2><table><thead><tr><th>Issued</th><th>Reference</th><th>Direction</th><th>Amount</th></tr></thead><tbody>${docs.filter(d=>d.issueDate>=from).map(d=>row([d.issueDate,d.number,side(d.direction),billingMoney(d.amountCents)])).join("")}</tbody></table><h2>Applied payments, credits, offsets and reversals</h2><table><thead><tr><th>Applied date</th><th>Reference</th><th>Type / invoice</th><th>Applied amount</th></tr></thead><tbody>${allocations.filter(a=>a.date>=from).map(a=>row([a.date,a.reference,`${a.kind} / ${docs.find(d=>d.id===a.documentId)?.number}`,billingMoney(a.amountCents)])).join("")}</tbody></table><p>Unapplied cash remains separate from invoice balances. Review unapplied payments and disputes in the vendor account.</p>`;
  }
  return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)} - ${esc(model.vendor.name)}</title><style>body{font:14px/1.5 Arial,sans-serif;color:#13233c;max-width:1000px;margin:30px auto;padding:0 24px}header{display:flex;justify-content:space-between;border-bottom:3px solid #29486f;padding-bottom:18px}h1{font-size:24px}h2{font-size:18px}small{font-size:12px}table{border-collapse:collapse;width:100%;margin:18px 0}th,td{text-align:left;padding:9px;border-bottom:1px solid #d3dce8;vertical-align:top}th{background:#f0f4f9}.warning{font-weight:bold;color:#8a4300}footer{margin-top:30px;font-size:12px;color:#526174}@media print{body{margin:0}thead{display:table-header-group}tr{break-inside:avoid}}</style></head><body><header><div><b>Time Motor Sales</b><br>1101 E. Lake Street<br>Minneapolis, MN 55407</div><div><b>${esc(model.vendor.name)}</b><br>${esc(model.vendor.address)}<br>${esc(model.vendor.number)}</div></header><h1>${esc(title)}</h1>${body}<footer>Template v${model.templateVersion}. Generated from saved vendor records. No bank transfer or external delivery is performed by printing this document. Use your browser's Print / Save as PDF command.</footer></body></html>`;
}
